<?php require_once __DIR__.'/bootstrap.php';$u=require_login();$rows=db()->query("SELECT i.*,COUNT(s.id) records FROM indicators i LEFT JOIN submissions s ON s.indicator_id=i.id GROUP BY i.id ORDER BY i.code")->fetchAll(); ?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Indicators | ISLANDS</title><link rel="stylesheet" href="assets/app.css"></head><body><div class="app-shell"><?php include __DIR__.'/partials/sidebar.php'; ?><main class="main"><header class="topbar"><div><div class="eyebrow">RESULTS FRAMEWORK</div><h1>GEB indicator catalogue</h1><p class="muted">Programme indicators available for reporting.</p></div></header><section class="indicator-grid"><?php foreach($rows as $i): ?><article class="indicator-card"><div class="indicator-top"><span class="code"><?=e($i['code'])?></span><span class="level"><?=e($i['level'])?></span></div><h3><?=e($i['name'])?></h3><p><?=e($i['description'])?></p><div class="indicator-foot"><span><?=e($i['unit']??'')?></span><strong><?=e((string)$i['records'])?> records</strong></div></article><?php endforeach; ?></section></main></div></body></html>
